+            "load": {"submitted": 3, "completed": 2, "failed": 1, "num_bytes": 8192},
+            "store": {"submitted": 1, "completed": 0, "failed": 0, "num_bytes": 0},
+        }))
+        .unwrap();
+        let stats = SchedulerStats {
+            kv_connector_stats: Some(kv_connector_stats),
